SELECT p.gender, p.age, d.icd_code, COUNT(DISTINCT pr.procedure_id) AS procedure_count, AVG(i.los) AS avg_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) / NULLIF(COUNT(DISTINCT i.subject_id), 0) AS mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id JOIN procedures_icd pr ON a.subject_id = pr.subject_id AND a.hadm_id = pr.hadm_id AND pr.charttime BETWEEN i.intime AND i.intime + interval '72 hours' WHERE p.gender = 'M' AND p.age = 49 AND d.icd_code = '4599' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) BETWEEN 44 AND 54 GROUP BY p.gender, p.age, d.icd_code ORDER BY procedure_count DESC NULLS LAST, avg_los NULLS LAST, mortality_rate NULLS LAST;